{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "@id": "https://dsdproperties.in/blog/igrsup-lucknow-property-search-tutorial#faq-1",
      "name": "What is IGRSUP and what is its full form?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "IGRSUP stands for Inspector General of Registration and Stamps, Uttar Pradesh. It is the official online portal of the UP Stamp and Registration Department at igrsup.gov.in. The portal digitises property registration, stamp duty payment, property search, encumbrance certificate applications, and e-stamp verification for all districts of UP including Lucknow."
      }
    },
    {
      "@type": "Question",
      "@id": "https://dsdproperties.in/blog/igrsup-lucknow-property-search-tutorial#faq-2",
      "name": "How do I search a property on IGRSUP in Lucknow?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Visit igrsup.gov.in and click on Sampatti Vivaran or Property Details. Choose Rural or Urban Properties based on location. For rural properties enter district, tehsil, village, and khasra number. For urban properties enter district and Property ID. Fill captcha and submit. The portal displays all registered transactions. When we checked igrsup.gov.in on 17 October 2026, the property search links opened a User Login page (user ID, password and captcha). If you do not have an account, use the Register Now option on the home page first."
      }
    },
    {
      "@type": "Question",
      "@id": "https://dsdproperties.in/blog/igrsup-lucknow-property-search-tutorial#faq-3",
      "name": "Is IGRSUP property search free to use?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "When we checked igrsup.gov.in on 17 October 2026, the property search links opened a User Login page (user ID, password and captcha). If you do not have an account, use the Register Now option on the home page first. You only need property details like district, tehsil, village, and khasra number for rural, or district and Property ID for urban. Paid services include property registration fees, stamp duty payments, EC applications (Rs.200-500), and certified copy requests."
      }
    },
    {
      "@type": "Question",
      "@id": "https://dsdproperties.in/blog/igrsup-lucknow-property-search-tutorial#faq-4",
      "name": "What is the difference between IGRSUP and UP Bhulekh?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "IGRSUP (igrsup.gov.in) is the Stamp and Registration Department portal showing registered document transactions — sale deeds, mortgages, gifts. UP Bhulekh (upbhulekh.gov.in) is the Revenue Department portal showing current land ownership through Khatauni with khasra and gata details. For complete verification both must be checked — IGRSUP for transaction history, UP Bhulekh for current ownership."
      }
    },
    {
      "@type": "Question",
      "@id": "https://dsdproperties.in/blog/igrsup-lucknow-property-search-tutorial#faq-5",
      "name": "How far back does IGRSUP property search data go?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "IGRSUP digital property records reliably cover transactions from approximately 2005 onwards, with comprehensive data from 2017. For pre-2005 transactions, manual search at Sub-Registrar Office is required. IGRSUP Index separately covers properties registered after December 5, 2017 with address-based search."
      }
    },
    {
      "@type": "Question",
      "@id": "https://dsdproperties.in/blog/igrsup-lucknow-property-search-tutorial#faq-6",
      "name": "What are the stamp duty and registration charges in Lucknow 2026?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Lucknow 2026 rates: Stamp duty 7 percent for male buyers, 6 percent for female buyers on property up to Rs 1 crore (7 percent above that), joint buyers 6.5 percent. Registration is flat 1 percent. The women's 1 percent concession limit was raised from Rs 10 lakh to Rs 1 crore in July 2025. Blood relative gift deeds carry flat Rs.5,000 stamp duty. Calculated on higher of transaction value or circle rate."
      }
    },
    {
      "@type": "Question",
      "@id": "https://dsdproperties.in/blog/igrsup-lucknow-property-search-tutorial#faq-7",
      "name": "Can I verify an e-stamp certificate on IGRSUP?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes, IGRSUP has E-Stamp Satyapan verification tool. It redirects to SHCIL portal. Enter the UIN from e-stamp certificate, issue date, and duty type. Submit captcha and click Verify. System confirms whether e-stamp is genuine, cancelled, or invalid in under 30 seconds. Essential check to catch forged stamp papers before accepting any property document."
      }
    },
    {
      "@type": "Question",
      "@id": "https://dsdproperties.in/blog/igrsup-lucknow-property-search-tutorial#faq-8",
      "name": "Which Sub-Registrar Office should I select for my Lucknow property?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Lucknow has five SROs: Lucknow Sadar (Hazratganj, Aminabad), Sarojini Nagar (Sushant Golf City, Shaheed Path), Malihabad (western rural), Mohanlalganj (southern rural), Bakshi Ka Talab (northern rural). Use Know Your Office feature on IGRSUP by entering district, tehsil, village to find correct SRO. Wrong SRO selection is the most common cause of failed searches."
      }
    },
    {
      "@type": "Question",
      "name": "What is the IGRSUP Index?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The IGRSUP Index is a search option for deeds registered after 5 December 2017. It lets you search by address details such as tehsil, colony and mohalla name, so you can find a deed even without the khasra number or property ID. For deeds registered before that date, use the Sampatti Vivaran search by khasra or property ID, or ask at the Sub-Registrar Office."
      }
    },
    {
      "@type": "Question",
      "name": "Do I need to log in to search property on IGRSUP?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "When we checked igrsup.gov.in on 17 October 2026, the property search links opened a User Login page (user ID, password and captcha). If you do not have an account, use the Register Now option on the home page first. Once logged in, choose rural or urban property and enter the district, tehsil, village and khasra number, or the district and property ID."
      }
    }
  ]
}
